import json

def build_skeleton(input_2s, height=19, width=13):
    """Build the H-like skeleton from input 2s."""
    output = [[0] * width for _ in range(height)]

    # Find the primary horizontal row
    row_2s = {}
    for r, c in input_2s:
        if r not in row_2s:
            row_2s[r] = []
        row_2s[r].append(c)

    max_span = 0
    primary_row = None
    for r, cols in row_2s.items():
        span = max(cols) - min(cols) + len(cols)
        if span > max_span:
            max_span = span
            primary_row = r

    primary_cols = sorted([c for r, c in input_2s if r == primary_row])
    if not primary_cols:
        primary_cols = sorted(input_2s)[0][1]
    min_col = min(primary_cols)
    max_col = max(primary_cols)

    band_cols = set()
    for r, c in input_2s:
        if r != primary_row:
            band_cols.add(c)

    print(f"Primary row: {primary_row}, cols: {primary_cols}")
    print(f"Band cols: {sorted(band_cols)}")

    # Place 2s
    for r, c in input_2s:
        output[r][c] = 2

    # Fill horizontal
    for c in range(min_col, max_col + 1):
        if output[primary_row][c] == 0:
            output[primary_row][c] = 3

    # Fill verticals
    for c in band_cols:
        col_2s = [r for r, c2 in input_2s if c2 == c]
        non_primary = [r for r in col_2s if r != primary_row]
        if non_primary:
            target_r = non_primary[0]
            start, end = min(primary_row, target_r), max(primary_row, target_r)
            for r in range(start, end):
                if output[r][c] == 0:
                    output[r][c] = 3

    return output

