def transform_v3(grid):
    """
    Transform v3: Better implementation based on closer analysis.

    The rule:
    1. Find primary row (row with most 2s, or max column if no pair row)
    2. Draw horizontal bar on primary row from leftmost to rightmost 2 in that row
    3. For each column with a 2, draw vertical line from that 2 to the primary row
    4. Vertical lines end when they hit the primary row
    """
    height = len(grid)
    width = len(grid[0]) if grid else 0

    input_2s = [(r, c) for r in range(height) for c in range(width) if grid[r][c] == 2]

    if not input_2s:
        return [[0] * width for _ in range(height)]

    output = [[0] * width for _ in range(height)]

    # Step 1: Find primary row
    row_counts = {}
    for r, c in input_2s:
        row_counts[r] = row_counts.get(r, 0) + 1

    has_multiple = any(count > 1 for count in row_counts.values())

    if has_multiple:
        primary_row = max(row_counts.items(), key=lambda x: x[1])[0]
    else:
        max_col = max(c for r, c in input_2s)
        primary_row = [r for r, c in input_2s if c == max_col][0]

    # Step 2: Find cols and rows for primary row
    primary_rows = sorted([r for r, c in input_2s if r == primary_row])
    if len(primary_rows) >= 2:
        min_col = primary_rows[0]
        max_col = primary_rows[-1]
    else:
        # Only one 2 on primary row - use spine column as start
        spine_col = max(col_counts := {c: sum(1 for r, c2 in input_2s if c2 == c) for c in set(c for r, c in input_2s)}, key=lambda x: col_counts[x])[0]
        min_col = spine_col
        max_col = max(c for r, c in input_2s)

    # Step 3: Place 2s and draw horizontal bar
    for r, c in input_2s:
        output[r][c] = 2

    for c in range(min_col, max_col + 1):
        if output[primary_row][c] == 0:
            output[primary_row][c] = 3

    # Step 4: For each column with 2s, draw vertical line to primary row
    # (but don't overwrite the 2s themselves)
    for r, c in input_2s:
        if c != min_col or r == primary_row:  # Don't override spine or primary position
            # Extend vertically toward primary row, stopping before 2s
            if r < primary_row:
                # Above primary - fill from r+1 to primary_row
                for row in range(r + 1, primary_row):
                    if output[row][c] == 0:
                        output[row][c] = 3
            else:
                # Below primary - fill from primary_row+1 to r-1
                for row in range(primary_row + 1, r):
                    if output[row][c] == 0:
                        output[row][c] = 3

    return output

