def transform_v4(grid):
    """
    Transform v4: Connect 2s to primary row with vertical lines.
    """
    height = len(grid)
    width = len(grid[0]) if grid else 0

    input_2s = [(r, c) for r in range(height) for c in range(width) if grid[r][c] == 2]

    if not input_2s:
        return [[0] * width for _ in range(height)]

    output = [[0] * width for _ in range(height)]

    # Find primary row
    row_counts = {}
    for r, c in input_2s:
        row_counts[r] = row_counts.get(r, 0) + 1

    has_multiple = any(count > 1 for count in row_counts.values())

    if has_multiple:
        primary_row = max(row_counts.items(), key=lambda x: x[1])[0]
    else:
        max_col = max(c for r, c in input_2s)
        primary_row = [r for r, c in input_2s if c == max_col][0]

    # Step 1: Place 2s
    for r, c in input_2s:
        output[r][c] = 2

    # Step 2: Draw horizontal bar on primary row for spans
    # Find 2s on primary row
    primary_2s = sorted([c for r, c in input_2s if r == primary_row])

    # If there are 2s on primary row, draw horizontal between leftmost and rightmost
    if len(primary_2s) >= 2:
        min_col = primary_2s[0]
        max_col = primary_2s[-1]
        for c in range(min_col, max_col + 1):
            if output[primary_row][c] == 0:
                output[primary_row][c] = 3
    else:
        # Only one 2 on primary row - need to find the spine column
        # Spine column = column with most 2s (or the most extreme one that isn't on primary row)
        col_counts = {}
        for r, c in input_2s:
            col_counts[c] = col_counts.get(c, 0) + 1
        # Pick column with most 2s
        spine_col = max(col_counts.items(), key=lambda x: x[1])[0]

        # Spine 2s are the 2s in spine_col
        spine_2s_rows = sorted([r for r, c in input_2s if c == spine_col])
        min_col = spine_2s_rows[0]
        max_col = spine_2s_rows[-1]

        # Fill vertical on spine, horizontal on primary
        for c in range(min_col, max_col + 1):
            if output[primary_row][c] == 0:
                output[primary_row][c] = 3

    # Step 3: Draw vertical lines from each 2 to primary row
    for r, c in input_2s:
        if r == primary_row:
            continue  # Already handled by horizontal
        if output[r][c] != 2:
            continue  # Don't touch non-2 cells

        # Determine direction
        if r < primary_row:
            for row in range(r + 1, primary_row):
                if output[row][c] == 0:
                    output[row][c] = 3
        else:
            for row in range(primary_row + 1, r):
                if output[row][c] == 0:
                    output[row][c] = 3

    return output

