    # Find primary row
    row_counts = {}
    for r, c in input_2s:
        row_counts[r] = row_counts.get(r, 0) + 1

    has_multiple = any(count > 1 for count in row_counts.values())

    if has_multiple:
        primary_row = max(row_counts.items(), key=lambda x: x[1])[0]
    else:
        max_col = max(c for r, c in input_2s)
        primary_row = [r for r, c in input_2s if c == max_col][0]

    # Step 1: Place 2s
    for r, c in input_2s:
        output[r][c] = 2

    # Step 2: Draw horizontal bar on primary row for spans
    primary_2s = sorted([c for r, c in input_2s if r == primary_row])

    if len(primary_2s) >= 2:
        min_col = primary_2s[0]
        max_col = primary_2s[-1]
        # Clamp to valid grid columns
        min_col = max(0, min_col)
        max_col = min(width - 1, max_col)
        for c in range(min_col, max_col + 1):
            if output[primary_row][c] == 0:
                output[primary_row][c] = 3
    else:
        # Only one 2 on primary row - need spine
        col_counts = {c: sum(1 for r, c2 in input_2s if c2 == c) for c in set(c for r, c in input_2s)}
        # Pick column with most 2s
        spine_col = max(col_counts.items(), key=lambda x: x[1])[0]

        spine_2s_rows = sorted([r for r, c in input_2s if c == spine_col])
        min_col = spine_2s_rows[0]
        max_col = spine_2s_rows[-1]

        # Clamp and fill vertical on spine
        min_col = max(0, min_col)
        max_col = min(width - 1, max_col)
        for c in range(min_col, max_col + 1):
            if output[primary_row][c] == 0:
                output[primary_row][c] = 3
                output[spine_col][c] = 3  # Horizontal on primary

        # Fill vertical on spine column
        for r in range(min_col, max_col + 1):
            if r not in spine_2s_rows and r >= min_col and r <= max_col:
                output[r][c] = 3

    # Step 3: Draw vertical lines from each 2 to primary row
    for r, c in input_2s:
        if r == primary_row:
            continue
        if output[r][c] != 2:
            continue

        if r < primary_row:
            for row in range(r + 1, primary_row):
                if row < 0 or row >= height:
                    continue
                if output[row][c] == 0:
                    output[row][c] = 3
        else:
            for row in range(primary_row + 1, r):
                if row < 0 or row >= height:
                    continue
                if output[row][c] == 0:
                    output[row][c] = 3

    return output

