def transform_v6(grid):
    """
    Transform v6: Final logic - clear and simple.

    1. Find primary row (row with pairs, or max column if no pairs)
    2. Find spine col (column with most 2s)
    3. On primary row: draw horizontal from spine_col to primary 2's column
    4. On spine col: draw vertical between spine 2s (fill with 3s)
    5. For every non-spine column with a 2: connect to primary row vertically
    6. (6,2) and (10,8) don't get connected because they're in non-spine cols
       but don't hit the primary row either (their connection path is blocked?)
    """
    height = len(grid)
    width = len(grid[0]) if grid else 0

    input_2s = [(r, c) for r in range(height) for c in range(width) if grid[r][c] == 2]

    if not input_2s:        
        return [[0] * width for _ in range(height)]

    output = [[0] * width for _ in range(height)]

    # Find primary row
    row_counts = {}
    for r, c in input_2s:
        row_counts[r] = row_counts.get(r, 0) + 1

    has_multiple = any(count > 1 for count in row_counts.values())
    if has_multiple:
        primary_row = max(row_counts.items(), key=lambda x: x[1])[0]
    else:
        max_col = max(c for r, c in input_2s)
        primary_row = [r for r, c in input_2s if c == max_col][0]

    # Find spine col (most 2s)
    col_counts = {c: sum(1 for r, c2 in input_2s if c2 == c) for c in set(c for r, c in input_2s)}
    spine_col = max(col_counts.items(), key=lambda x: x[1])[0]

    # Get primary 2's column
    primary_cols = [c for r, c in input_2s if r == primary_row]
    primary_col = primary_cols[0] if primary_cols else spine_col

    # Get spine 2s rows
    spine_2s_rows = sorted([r for r, c in input_2s if c == spine_col])

    # Step 1: Place all 2s
    for r, c in input_2s:
        output[r][c] = 2

    # Step 2: Horizontal on primary row from spine_col to primary_col
    min_h = min(spine_col, primary_col)
    max_h = max(spine_col, primary_col)
    for c in range(min_h, max_h + 1):
        if output[primary_row][c] == 0:
            output[primary_row][c] = 3

    # Step 3: Vertical on spine col between spine 2s
    # Fill 3s between spine 2s (not including the 2s themselves)
    for r in range(spine_2s_rows[0] + 1, spine_2s_rows[-1]):
        if output[r][spine_col] == 0:
            output[r][spine_col] = 3

    # Step 4: For each non-spine column 2, connect toward primary row
    for r, c in input_2s:
        if c == spine_col:
            continue  # Already handled

        # Connect toward primary row
        if r < primary_row:
            # Above primary - extend downward
            for row in range(r + 1, min(primary_row, height)):
                if output[row][c] == 0:
                    output[row][c] = 3
        else:
            # Below primary - extend upward  
            for row in range(r - 1, primary_row - 1, -1):
                if output[row][c] == 0:
                    output[row][c] = 3

    return output

